{"success": true, "data": {"stdout": "def load_wikievents_data(data_path, event_type_mapping=None):
    """Load WikiEvents JSONL data for event extraction.

    Args:
        data_path: Path to WikiEvents JSONL file.
        event_type_mapping: Dict mapping full event type names to short names.
    """
    samples = []
    with open(data_path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                doc = json.loads(line)
            except json.JSONDecodeError:
                continue
            doc_id = doc["doc_id"]
            text = doc["text"]

            entity_id_to_type = {}
            for ent in doc.get("entity_mentions", []):
                entity_id_to_type[ent["id"]] = ent["entity_type"]

            gold_entities = []
            seen = set()
            for ent in doc.get("entity_mentions", []):
                key = (ent["text"], ent["entity_type"])
                if key not in seen:
                    seen.add(key)
                    gold_entities.append({"text": ent["text"], "type": ent["entity_type"]})

            gold_events = []
            for evt in doc.get("event_mentions", []):
                trigger = evt["trigger"]
                raw_event_type = evt["event_type"]
                if event_type_mapping:
                    event_type = event_type_mapping.get(raw_event_type, raw_event_type)
                else:
                    event_type = raw_event_type
                arguments = []
                for arg in evt.get("arguments", []):
                    ent_type = entity_id_to_type.get(arg.get("entity_id", ""), "")
                    arguments.append({
                        "text": arg["text"],
                        "role": arg["role"],
                        "entity_type": ent_type,
                    })
                gold_events.append({
                    "trigger": trigger["text"],
                    "event_type": event_type,
                    "arguments": arguments,
                })

            samples.append({
                "doc_id": doc_id,
                "input_text": text,
                "gold_entities": gold_entities,
                "gold_events": gold_events,
                "gold_relations": [],
            })
    return samples


